  root.addEventListener('pointerover',e=>{const host=e.target.closest('.tc-layout-launcher');if(!host||e.pointerType==='touch')return;clearTimeout(viewMenuTimer);if(!ui.menu){ui.menu=true;host.insertAdjacentHTML('beforeend',viewMenu());host.querySelector('.tc-view-trigger').setAttribute('aria-expanded','true');}},{signal});
